function portalView(){return{
  noShell:true,title:'Portal de entrada',
  html:`<main id="app-main" class="portal-page portal-cinematic" style="--portal-image:url('/assets/sod-visual/062.png')"><div class="portal-shade"></div><section class="portal-intro"><div class="portal-brand"><img src="/assets/sod-visual/002.png" alt=""><span>SØD</span></div><p class="eyebrow">AGENTE DE CLARIDAD MENTAL</p><h1>Entrá.</h1><p>No necesitás entender todo este lugar ahora. Solo traer aquello que hoy necesita ser observado.</p><div class="actions"><button class="btn btn-primary" data-enter>Entrar</button><a class="btn btn-ghost" href="/entrar" data-link>Ya tengo una identidad</a></div><p class="portal-manifesto">SØD no se define por lo que sabe. Se define por cómo piensa.</p></section></main>`,
  mount(){document.querySelector('[data-enter]').onclick=()=>{store.update(s=>{s.profile.mode='guest';s.onboarding.completed=false;return s});navigate('/onboarding')}}
}}

function authView(mode='login'){const register=mode==='register';return{
  title:register?'Crear identidad':'Entrar',
  html:`<main id="app-main" class="section"><div class="container" style="max-width:620px"><div class="card"><div class="card-body"><p class="eyebrow">ACCESO SØD</p><h1>${register?'Crear identidad':'Volver al ecosistema'}</h1><p class="muted">Autenticación MVP local. En producción este adaptador se reemplaza por sesiones seguras sin alterar la experiencia.</p><form class="form" id="auth-form">${register?`<div class="field"><label for="name">Nombre visible</label><input id="name" name="name" required maxlength="80" autocomplete="name"></div>`:''}<div class="field"><label for="email">Email</label><input id="email" name="email" type="email" required autocomplete="email"></div><div class="field"><label for="password">Contraseña</label><input id="password" name="password" type="password" required minlength="6" autocomplete="${register?'new-password':'current-password'}"></div><button class="btn btn-primary" type="submit">${register?'Crear cuenta local':'Entrar'}</button></form><div class="divider"></div><p class="muted">${register?'¿Ya tenés una identidad?':'¿Todavía no tenés una cuenta?'} <a style="color:var(--cyan)" href="/${register?'entrar':'registro'}" data-link>${register?'Entrar':'Registrarme'}</a></p></div></div></div></main>`,
  mount(){document.querySelector('#auth-form').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const email=String(fd.get('email'));const name=register?String(fd.get('name')):email.split('@')[0];store.update(s=>{s.profile={name,email,mode:'local'};return s});toast(register?'Identidad creada':'Sesión iniciada');navigate(state().onboarding.completed?'/hub':'/onboarding')}}
}}

function onboardingView(){const current=state().onboarding;return{
  noShell:true,title:'Calibración inicial',
  html:`<main id="app-main" class="onboarding onboarding-visual" style="--onboarding-image:url('/assets/sod-visual/063.png')"><div class="onboarding-atmosphere"></div><section class="onboarding-shell"><div class="stepper"><span class="active"></span><span></span><span></span><span></span></div><div class="card onboarding-card"><div class="card-body" id="onboarding-content"></div></div></section></main>`,
  mount(){let step=0;const draft={...current};const root=document.querySelector('#onboarding-content');const shell=document.querySelector('.onboarding');const backgrounds=['063','063','064','064'];const steps=[
    ()=>`<p class="eyebrow">01 · RECONOCIMIENTO</p><h1>¿Qué necesitás hoy?</h1><p class="lead">No estás eligiendo una función. Estás nombrando la necesidad desde la que entrás.</p><div class="option-grid">${[['claridad','Comprender algo que hoy está confuso'],['cultivar','Sostener un cambio en el tiempo'],['direccion','Recordar hacia dónde quiero ir'],['observar','Reconocer en quién me estoy convirtiendo']].map(([v,t])=>`<label class="option ${draft.intention===v?'selected':''}"><input type="radio" name="intention" value="${v}" ${draft.intention===v?'checked':''}><strong>${t}</strong></label>`).join('')}</div>`,
    ()=>`<p class="eyebrow">02 · PRESENCIA</p><h1>¿Querés entrar con sonido?</h1><p class="lead">El silencio también es parte de SØD. Nada comienza sin tu consentimiento.</p><div class="option-grid">${[['true','Activar ambiente','Una capa sonora sutil, sin voz.'],['false','Entrar en silencio','La experiencia permanece completa.']].map(([v,t,d])=>`<label class="option ${String(draft.audio)===v?'selected':''}"><input type="radio" name="audio" value="${v}" ${String(draft.audio)===v?'checked':''}><strong>${t}</strong><small>${d}</small></label>`).join('')}</div>`,
    ()=>`<p class="eyebrow">03 · MOVIMIENTO</p><h1>Calibrá la intensidad</h1><p class="lead">El mundo puede respirar sin quitarte control.</p><div class="option-grid">${[['true','Experiencia viva','Movimiento ambiental, partículas y transiciones.'],['false','Movimiento reducido','Composición estable y mínima animación.']].map(([v,t,d])=>`<label class="option ${String(draft.motion)===v?'selected':''}"><input type="radio" name="motion" value="${v}" ${String(draft.motion)===v?'checked':''}><strong>${t}</strong><small>${d}</small></label>`).join('')}</div>`,
    ()=>`<p class="eyebrow">04 · CALIBRACIÓN</p><h1>El núcleo te reconoce.</h1><p class="lead">Podrás cambiar audio, calidad, movimiento, privacidad y memoria en cualquier momento.</p><div class="option-grid">${[['auto','Automática','El sistema adapta la escena.'],['low','Esencial','Menor densidad visual.'],['high','Alta','Máxima presencia para equipos capaces.']].map(([v,t,d])=>`<label class="option ${draft.quality===v?'selected':''}"><input type="radio" name="quality" value="${v}" ${draft.quality===v?'checked':''}><strong>${t}</strong><small>${d}</small></label>`).join('')}</div>`
  ];
  const render=()=>{shell.style.setProperty('--onboarding-image',`url('/assets/sod-visual/${backgrounds[step]}.png')`);root.innerHTML=`${steps[step]()}<div class="actions"><button class="btn" data-back ${step===0?'disabled':''}>Atrás</button><button class="btn btn-primary" data-next>${step===3?'Entrar al Hub':'Continuar'}</button></div>`;document.querySelectorAll('.stepper span').forEach((el,i)=>el.classList.toggle('active',i<=step));root.querySelectorAll('input').forEach(input=>input.onchange=()=>{if(input.name==='audio'||input.name==='motion')draft[input.name]=input.value==='true';else draft[input.name]=input.value;render()});root.querySelector('[data-back]').onclick=()=>{if(step>0){step--;render()}};root.querySelector('[data-next]').onclick=async()=>{if(step<3){step++;render();return}store.update(s=>{s.onboarding={...draft,completed:true};s.settings={...s.settings,audio:draft.audio,motion:draft.motion,quality:draft.quality};s.journey.startedAt=s.journey.startedAt||new Date().toISOString();return s});if(draft.audio)await ambient.start(state().settings.ambientVolume);navigate('/hub')}};render()}
}}

function selectSeedFor(text=''){
  const normalized=text.toLowerCase();
  let best=seeds[0],score=-1;
  for(const seed of seeds){
    const haystack=`${seed.title} ${seed.interpretation} ${(seed.keywords||[]).join(' ')}`.toLowerCase();
    const current=(seed.keywords||[]).reduce((sum,k)=>sum+(normalized.includes(String(k).toLowerCase())?3:0),0)+normalized.split(/\s+/).reduce((sum,w)=>sum+(w.length>4&&haystack.includes(w)?1:0),0);
    if(current>score){score=current;best=seed}
  }
  return best;
}

function dialogueModal(){navigate('/experiencia')}


function hubView(){const s=state();const groups=[
  {id:'understand',label:'Necesito comprender',items:['sod','library','elements33']},
  {id:'cultivate',label:'Necesito cultivar',items:['seeds','habits']},
  {id:'direction',label:'Necesito dirección',items:['dreams','identity']},
  {id:'observe',label:'Necesito observar',items:['observatory']}
];return{
  title:'Hub Central',immersive:true,
  html:`<main id="app-main" class="hub-page hub-v3">
    <canvas id="hub-canvas" class="hub-canvas" tabindex="0" aria-label="Hub panorámico SØD. Arrastrá para explorar, tocá los portales o seleccioná una necesidad humana."></canvas>
    <div class="hub-vignette"></div>
    <div class="hub-title"><span class="eyebrow">PRESENCIA SØD</span><strong>¿Qué necesitás hoy?</strong><small>Elegí una necesidad. El mundo te mostrará una puerta.</small></div>
    <div class="hub-minimal-status"><span class="dot"></span><span>Presencia activa</span></div>
    <button class="hub-oracle-button" data-insight aria-label="Abrir mensaje y huellas"><span>Ø</span><small>Mensaje</small></button>
    <aside class="hub-insight-drawer" id="hub-insight" aria-label="Mensaje de SØD y huellas del recorrido">
      <button class="icon-button drawer-close" data-insight-close aria-label="Cerrar panel">✕</button>
      <p class="eyebrow">SØD</p><p class="hub-insight-message" id="daily-message">${escapeHtml(dailyFallback.message)}</p>
      <button class="btn btn-primary" data-dialogue>Entrar en conversación</button>
      <div class="hub-drawer-divider"></div>
      <p class="eyebrow">HUELLAS</p>
      <div class="hub-signal-row"><span>${s.collection.seeds.length}</span><small>Semillas descubiertas</small></div>
      <div class="hub-signal-row"><span>${(s.codes||[]).length}</span><small>Códigos conservados</small></div>
      <div class="hub-signal-row"><span>${s.journey.completedDays.length}</span><small>tramos sostenidos</small></div>
      <a class="btn" href="/observatorio" data-link>Contemplar el Observatorio</a>
      <div class="hub-drawer-divider"></div>
      <p class="eyebrow">CLAVE DEL DÍA</p><strong class="mono" id="daily-key">${escapeHtml(dailyFallback.key)}</strong>
    </aside>
    <nav class="hub-need-dock" aria-label="Necesidades humanas">${groups.map((g,i)=>`<button data-need="${g.id}"><span>0${i+1}</span><strong>${g.label}</strong></button>`).join('')}</nav>
    <section class="hub-world-drawer" id="hub-world-drawer" aria-live="polite">
      <div class="hub-world-drawer-head"><div><p class="eyebrow">PUERTAS DISPONIBLES</p><h2 id="hub-drawer-title">Elegí una necesidad</h2></div><button class="icon-button" data-world-close aria-label="Cerrar puertas">✕</button></div>
      <div class="hub-world-grid" id="hub-world-grid"></div>
    </section>
    <div class="hub-controls-v3"><button class="icon-button glass-panel" data-recenter aria-label="Recentrar">⌖</button><button class="icon-button glass-panel" data-audio aria-label="Audio">${s.settings.audio?'◉':'○'}</button><button class="icon-button glass-panel" data-gyro aria-label="Giroscopio">◌</button><button class="icon-button glass-panel" data-fallback aria-label="Modo 2D">▦</button></div>
    <div class="spatial-prompt" id="spatial-prompt"></div>
    <div class="scene-mirror"><h2>Alternativa accesible del Hub</h2><ul>${universes.map(u=>`<li><a href="${universeRoute(u)}" data-link>${u.title}: ${u.humanNeed}</a></li>`).join('')}</ul></div>
  </main>`,
  mount(){
    let scene;const canvas=document.querySelector('#hub-canvas');const prompt=document.querySelector('#spatial-prompt');const drawer=document.querySelector('#hub-world-drawer');const grid=document.querySelector('#hub-world-grid');const title=document.querySelector('#hub-drawer-title');const insight=document.querySelector('#hub-insight');
    const openGroup=id=>{const group=groups.find(g=>g.id===id);if(!group)return;const items=group.items.map(slug=>universes.find(u=>u.slug===slug)).filter(Boolean);title.textContent=group.label;grid.innerHTML=items.map(u=>`<a href="${universeRoute(u)}" data-link class="hub-world-card" style="--world-color:${u.color};--world-image:url('${u.visual}')"><div class="hub-world-card-shade"></div><span class="hub-world-card-icon">${u.icon}</span><div><p class="eyebrow">${u.type}</p><h3>${u.title}</h3><p>${u.entryQuestion}</p></div></a>`).join('');bindRouteButtons(grid);drawer.classList.add('open')};
    scene=new HubScene(canvas,{settings:s.settings,onSelect:u=>navigate(universeRoute(u)),onOrb:dialogueModal,onHover:u=>{prompt.textContent=u?`${u.entryQuestion||u.title}`:'';prompt.classList.toggle('show',!!u)},onQuality:()=>{}});
    document.querySelectorAll('[data-need]').forEach(btn=>btn.onclick=()=>openGroup(btn.dataset.need));
    document.querySelector('[data-world-close]').onclick=()=>drawer.classList.remove('open');
    document.querySelector('[data-insight]').onclick=()=>insight.classList.toggle('open');
    document.querySelector('[data-insight-close]').onclick=()=>insight.classList.remove('open');
    document.querySelector('[data-dialogue]').onclick=dialogueModal;
    document.querySelector('[data-recenter]').onclick=()=>scene.recenter();
    document.querySelector('[data-fallback]').onclick=()=>navigate('/hub-2d');
    document.querySelector('[data-audio]').onclick=async e=>{const enabled=!state().settings.audio;store.update(x=>{x.settings.audio=enabled;return x});if(enabled)await ambient.start(state().settings.ambientVolume);else ambient.stop();e.currentTarget.textContent=enabled?'◉':'○'};
    document.querySelector('[data-gyro]').onclick=async e=>{try{const ok=await scene.enableGyro();if(ok){store.update(x=>{x.settings.gyro=true;return x});e.currentTarget.textContent='◉';toast('Giroscopio activado')}else toast('El permiso no fue concedido','error')}catch{toast('Giroscopio no disponible','error')}};
    api.getState().then(r=>{if(r.adminContent?.dailyMessage)document.querySelector('#daily-message').textContent=r.adminContent.dailyMessage;if(r.adminContent?.dailyKey)document.querySelector('#daily-key').textContent=r.adminContent.dailyKey}).catch(()=>{});
    return()=>scene.destroy();
  }
}}


function fallbackHubView(){return{title:'Hub accesible',html:`<main id="app-main" class="fallback-hub visual-page" style="--visual-bg:url('/assets/hub/hub-main-360.png')"><div class="visual-page-shade"></div><div class="container visual-page-content">${pageHero('MODO 2D','El mismo universo.<br><span style="color:var(--cyan)">Sin perder claridad.</span>','Todas las experiencias permanecen disponibles sin Canvas, movimiento ni giroscopio.',`<a class="btn btn-primary" href="/hub" data-link>Volver al modo inmersivo</a>`)}<div class="visual-card-grid">${universes.map(u=>`<a class="universe-visual-card" href="${universeRoute(u)}" data-link style="--card-image:url('${u.visual}')"><div class="universe-visual-shade"></div><div><span class="universe-icon">${u.icon}</span><p class="eyebrow">${u.type}</p><h3>${u.title}</h3><p>${u.entryQuestion}</p></div></a>`).join('')}</div></div></main>`}}

function universeView(slug){const u=universes.find(x=>x.slug===slug);if(!u)return notFoundView();const sod=u.slug==='sod';return{title:u.title,html:`<main id="app-main"><section class="universe-hero universe-visual-hero" style="--universe-glow:${u.color}55;--universe-image:url('${u.visual}')"><div class="universe-hero-shade"></div><div class="container"><p class="eyebrow">UNIVERSO · ${escapeHtml(u.title.toUpperCase())}</p><h1 class="page-title"><span style="color:${u.color}">${u.icon}</span> ${u.title}</h1><p class="universe-question">${u.entryQuestion}</p><p class="lead">${sod?'Traé lo que todavía no lográs ordenar. No necesitás formularlo perfectamente.':u.shortDescription}</p><div class="actions">${sod?'<a class="btn btn-primary" href="/experiencia" data-link>Comenzar conversación</a>':'<button class="btn btn-primary" data-start-practice>Entrar en la experiencia</button>'}<a class="btn btn-ghost" href="/hub" data-link>Volver al Hub</a></div></div></section><section class="cognitive-path-section"><div class="container"><div class="cognitive-path-intro"><p class="eyebrow">MÉTODO SØD</p><h2>${u.message}</h2><p>La experiencia busca una transición reconocible. No actividad vacía.</p></div><div class="cognitive-path">${u.practices.map((p,i)=>`<article class="cognitive-step" data-practice="${i}"><span class="cognitive-step-index">0${i+1}</span><div class="cognitive-step-line"></div><p class="eyebrow">${p.duration}</p><h3>${p.title}</h3><p>${p.instruction}</p><button class="btn btn-small">Explorar fase</button></article>`).join('')}</div></div></section></main>`,mount(){if(sod)return;const start=i=>openModal({title:u.practices[i].title,content:`<p class="eyebrow">${u.practices[i].duration}</p><h2>${u.practices[i].instruction}</h2><p class="muted">Esta es una práctica funcional con contenido placeholder. Registrá qué cambió entre el antes y el después.</p><form class="form" id="practice-form"><div class="field"><label for="practice-before">Antes</label><textarea id="practice-before" required placeholder="¿Cómo observabas esto antes?"></textarea></div><div class="field"><label for="practice-after">Después</label><textarea id="practice-after" required placeholder="¿Qué podés distinguir ahora?"></textarea></div><button class="btn btn-primary">Conservar integración</button></form>`,onMount:(root,close)=>{root.querySelector('form').onsubmit=e=>{e.preventDefault();toast('Integración registrada como placeholder funcional');close()}}});document.querySelector('[data-start-practice]')?.addEventListener('click',()=>start(0));document.querySelectorAll('[data-practice]').forEach(b=>b.onclick=()=>start(Number(b.dataset.practice)))}}}


function journeyView(){const s=state();const done=new Set(s.journey.completedDays);return{title:'Journey',html:`<main id="app-main">${pageHero('JOURNEY DE 14 DÍAS','La comprensión necesita<br><span style="color:var(--cyan)">ritmo, no presión.</span>','Un recorrido diario de observación, pregunta, práctica, registro e integración. Perder un día no borra el camino.')}<section class="section" style="padding-top:20px"><div class="container"><div class="card"><div class="card-body"><div style="display:flex;justify-content:space-between;gap:20px;align-items:end"><div><p class="eyebrow">PROGRESO</p><h2 style="font-size:40px;margin-bottom:8px">${done.size} de 14 integraciones</h2></div><span class="mono">${Math.round(done.size/14*100)}%</span></div><div class="progress"><span style="width:${done.size/14*100}%"></span></div></div></div><div class="journey-grid" style="margin-top:20px">${journeyDays.map(d=>`<article class="day-card ${done.has(d.day)?'completed':''} ${d.day===Math.min(done.size+1,14)?'current':''}" tabindex="0" data-day="${d.day}"><div class="day-number">DÍA ${String(d.day).padStart(2,'0')}</div><h3>${d.title}</h3><small class="muted">${d.practice}</small><div class="check">${done.has(d.day)?'✓':'·'}</div></article>`).join('')}</div></div></section></main>`,mount(){const openDay=day=>{const d=journeyDays[day-1];const completed=state().journey.completedDays.includes(day);openModal({title:`Día ${day} · ${d.title}`,content:`<p class="eyebrow">PREGUNTA</p><h2>${d.question}</h2><div class="divider"></div><p class="eyebrow">PRÁCTICA</p><p class="lead" style="font-size:20px">${d.practice}</p><form class="form" id="day-form"><div class="field"><label for="day-reflection">¿Qué observaste?</label><textarea id="day-reflection" placeholder="No busques escribir bien. Buscá registrar con precisión."></textarea></div><button class="btn btn-primary" type="submit">${completed?'Actualizar integración':'Completar día'}</button></form>`,onMount:(root,close)=>{root.querySelector('form').onsubmit=e=>{e.preventDefault();store.update(s=>{if(!s.journey.completedDays.includes(day))s.journey.completedDays.push(day);s.journey.completedDays.sort((a,b)=>a-b);return s});toast(`Día ${day} integrado`);close();navigate('/journey',{replace:true});window.dispatchEvent(new PopStateEvent('popstate'))}}})};document.querySelectorAll('[data-day]').forEach(card=>{card.onclick=()=>openDay(Number(card.dataset.day));card.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')openDay(Number(card.dataset.day))}})}}}

function bitacoraView(){return{title:'Bitácora',html:`<main id="app-main">${pageHero('BITÁCORA','Registrar convierte experiencia<br><span style="color:var(--cyan)">en información disponible.</span>','Creá, editá y eliminá registros. En esta versión quedan guardados localmente en este dispositivo.')}<section class="section" style="padding-top:10px"><div class="container grid grid-2"><div class="card"><div class="card-body"><h2>Nueva reflexión</h2><form class="form" id="reflection-form"><div class="field"><label for="reflection-title">Título</label><input id="reflection-title" name="title" maxlength="120" placeholder="Qué querés recordar"></div><div class="field"><label for="reflection-text">Registro</label><textarea id="reflection-text" name="text" required placeholder="Hecho, interpretación, emoción, decisión..."></textarea></div><button class="btn btn-primary" type="submit">Guardar registro</button></form></div></div><div><div class="toolbar"><input class="search-input" id="reflection-search" placeholder="Buscar en la bitácora"><span class="pill" id="reflection-count">0 registros</span></div><div id="reflection-list"><div class="skeleton" style="height:180px"></div></div></div></div></section></main>`,mount(){let items=[];const list=document.querySelector('#reflection-list');const render=(query='')=>{const filtered=items.filter(x=>(x.title+' '+x.text).toLowerCase().includes(query.toLowerCase()));document.querySelector('#reflection-count').textContent=`${items.length} registros`;list.innerHTML=filtered.length?filtered.map(x=>`<article class="card reflection"><time>${formatDate(x.updatedAt)}</time><h3>${escapeHtml(x.title)}</h3><p class="muted">${escapeHtml(x.text)}</p><div class="reflection-actions"><button class="btn btn-small" data-edit="${x.id}">Editar</button><button class="btn btn-small btn-danger" data-delete="${x.id}">Eliminar</button></div></article>`).join('<div style="height:10px"></div>'):'<div class="empty">Todavía no hay registros. La bitácora empieza cuando una observación se vuelve explícita.</div>';list.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>confirmAction('¿Eliminar este registro de forma permanente?',async()=>{await api.deleteReflection(b.dataset.delete);items=items.filter(x=>x.id!==b.dataset.delete);render(document.querySelector('#reflection-search').value);toast('Registro eliminado')}));list.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const item=items.find(x=>x.id===b.dataset.edit);openModal({title:'Editar reflexión',content:`<form class="form" id="edit-reflection"><div class="field"><label>Título<input name="title" value="${escapeHtml(item.title)}"></label></div><div class="field"><label>Registro<textarea name="text">${escapeHtml(item.text)}</textarea></label></div><button class="btn btn-primary">Guardar cambios</button></form>`,onMount:(root,close)=>{root.querySelector('form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const r=await api.updateReflection(item.id,{title:fd.get('title'),text:fd.get('text')});items=items.map(x=>x.id===item.id?r.item:x);render(document.querySelector('#reflection-search').value);close();toast('Registro actualizado')}}})})};api.getReflections().then(r=>{items=r.items;render()}).catch(err=>{list.innerHTML=`<div class="empty">${escapeHtml(err.message)}. Verificá que el servidor esté activo.</div>`});document.querySelector('#reflection-search').oninput=e=>render(e.target.value);document.querySelector('#reflection-form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{const r=await api.createReflection({title:fd.get('title'),text:fd.get('text')});items.unshift(r.item);e.currentTarget.reset();render();toast('Reflexión guardada')}catch(err){toast(err.message,'error')}}}}}

function libraryView(){return{title:'Biblioteca',html:`<main id="app-main" class="visual-page library-world" style="--visual-bg:url('/assets/sod-visual/039.png')"><div class="visual-page-shade"></div><div class="visual-page-content">${pageHero('BIBLIOTECA','Información que espera<br><span style="color:var(--cyan)">ser integrada.</span>','No es un catálogo. Es un archivo vivo de marcos, prácticas y mapas que pueden modificar una forma de observar.')}<section class="section library-archive"><div class="container"><div class="library-toolbar"><input class="search-input" id="library-search" placeholder="¿Qué necesitás comprender hoy?"><span class="pill">${libraryItems.length} piezas iniciales</span></div><div class="library-layout"><aside class="library-feature"><p class="eyebrow">PIEZA DESTACADA</p><div class="library-feature-symbol">Ø</div><h2>${libraryItems[0].title}</h2><p>${libraryItems[0].description}</p><button class="btn btn-primary" data-library="${libraryItems[0].id}">Abrir pieza viva</button></aside><div class="knowledge-shelf" id="library-grid">${libraryItems.slice(1).map(libraryCard).join('')}</div></div></div></section></div></main>`,mount(){const grid=document.querySelector('#library-grid');const render=q=>{const items=libraryItems.filter(x=>(x.title+x.description+x.type).toLowerCase().includes(q.toLowerCase()));grid.innerHTML=items.map(libraryCard).join('')||'<div class="empty">No encontramos una pieza con esa búsqueda.</div>';bindLibrary(document)};document.querySelector('#library-search').oninput=e=>render(e.target.value);bindLibrary(document)}}}


function libraryCard(item){const index=libraryItems.findIndex(x=>x.id===item.id);const icons=['⌑','◌','△','≋','◇','✧','Ø','✦'];return `<article class="knowledge-artifact" data-library="${item.id}"><span class="knowledge-index">${String(index+1).padStart(2,'0')}</span><div class="knowledge-icon">${icons[index%icons.length]}</div><div class="knowledge-copy"><p class="eyebrow">${item.type} · ${item.duration}</p><h3>${item.title}</h3><p>${item.description}</p></div><button class="btn btn-small">Abrir pieza</button></article>`}


function bindLibrary(root){root.querySelectorAll('[data-library]').forEach(b=>b.onclick=()=>{const item=libraryItems.find(x=>x.id===b.dataset.library);const seed=seeds.find(x=>x.id===item.seedId);openModal({title:item.title,content:`<p class="eyebrow">${item.type} · ${item.duration}</p><p class="lead" style="font-size:20px">${item.description}</p><div class="divider"></div><h3>Comprensión asociada</h3><p>${seed.interpretation}</p><h3>Aplicación</h3><p>${seed.application}</p><a class="btn" href="/semillas/${seed.id}" data-link>Ver Semilla completa</a>`})})}

function seedsView(){const all=seeds;return{title:'Semillas',html:`<main id="app-main" class="visual-page" style="--visual-bg:url('/assets/sod-visual/036.png')"><div class="visual-page-shade"></div><div class="visual-page-content">${pageHero('SEMILLAS SØD','Conocimiento vivo<br><span style="color:var(--green)">que ya estaba esperando.</span>','Las Semillas no se crean. Se descubren, se desbloquean, se cultivan y, cuando dejan evidencia, germinan.')}<section class="section" style="padding-top:10px"><div class="container"><div class="toolbar"><input class="search-input" id="seed-search" placeholder="Buscar una comprensión"><span class="pill">${all.length} Semillas canónicas</span></div><div class="seed-grid visual-seed-grid" id="seed-grid">${all.map(seedCard).join('')}</div></div></section></div></main>`,mount(){const grid=document.querySelector('#seed-grid');const render=q=>{grid.innerHTML=all.filter(x=>(x.title+x.interpretation+(x.keywords||[]).join(' ')).toLowerCase().includes(q.toLowerCase())).map(seedCard).join('')||'<div class="empty" style="grid-column:1/-1">No hay coincidencias.</div>';bindSeedCards(grid)};document.querySelector('#seed-search').oninput=e=>render(e.target.value);bindSeedCards(grid)}}}
function seedCard(seed){return `<a class="seed-visual-card" href="/semillas/${seed.id}" data-link style="--seed-image:url('${seed.image}')"><div class="seed-visual-shade"></div><div class="seed-card-content"><span class="eyebrow">${seed.state==='latent'?'LATENTE':'DESCUBIERTA'}</span><div class="seed-symbol">${seed.glyph||'Ø'}</div><blockquote>${escapeHtml(seed.title)}</blockquote><p>${escapeHtml(seed.interpretation)}</p><div class="tag-list">${(seed.keywords||[]).map(k=>`<span class="tag">${escapeHtml(k)}</span>`).join('')}</div></div></a>`}
function bindSeedCards(){/* links are handled by the router */}
function seedDetailView(id){const seed=seeds.find(x=>x.id===id);if(!seed)return notFoundView();const saved=state().collection.seeds.includes(id);return{title:seed.title,html:`<main id="app-main"><section class="seed-detail-hero" style="--seed-image:url('${seed.image}')"><div class="seed-detail-shade"></div><div class="container seed-detail-content"><p class="eyebrow">SEMILLA ${String(seed.number).padStart(2,'0')} · ${seed.state.toUpperCase()}</p><h1 class="page-title">${escapeHtml(seed.title)}</h1><p class="lead">${escapeHtml(seed.interpretation)}</p><div class="actions"><button class="btn btn-primary" data-save-seed>${saved?'Dejar de cultivar':'Descubrir y cultivar'}</button><a class="btn" href="/semillas" data-link>Volver</a></div></div></section><section class="section"><div class="container grid grid-2"><article class="card"><div class="card-body"><p class="eyebrow">COMPRENSIÓN</p><p class="lead" style="font-size:22px">${escapeHtml(seed.interpretation)}</p></div></article><article class="card"><div class="card-body"><p class="eyebrow">PRÁCTICA DE CULTIVO</p><p class="lead" style="font-size:22px">${escapeHtml(seed.application)}</p></div></article></div></section></main>`,mount(){document.querySelector('[data-save-seed]').onclick=e=>{store.update(s=>{const list=s.collection.seeds;const i=list.indexOf(id);i>=0?list.splice(i,1):list.push(id);return s});e.currentTarget.textContent=state().collection.seeds.includes(id)?'Dejar de cultivar':'Descubrir y cultivar';toast('Estado de la Semilla actualizado')}}}}

function elementsView(){return{title:'Elementos 33',html:`<main id="app-main" class="elements-sanctuary" style="--elements-bg:url('/assets/sod-visual/037.png')"><div class="elements-sanctuary-shade"></div><section class="elements-intro container"><p class="eyebrow">NÚCLEO FILOSÓFICO</p><h1>Cinco fuerzas.<br><span>Ciento sesenta y cinco lecturas.</span></h1><p>Elementos 33 no es una grilla de objetos. Es un mapa monumental del desarrollo humano. Esta V3 utiliza placeholders visuales hasta integrar las piezas definitivas.</p><div class="elements-law"><span>12 Velo</span><span>12 Remez</span><span>6 Derash</span><span>2 SØD</span><span>1 SØD²</span></div></section><section class="force-gates container">${elementDefinitions.map((e,i)=>`<a class="force-gate" href="/elementos/${e.key}" data-link style="--element:${e.color};--element-image:url('${e.visual}')"><div class="force-gate-image"></div><div class="force-gate-shade"></div><span class="force-number">0${i+1}</span>${e.placeholder?'<span class="placeholder-badge">PLACEHOLDER VISUAL</span>':''}<div class="force-copy"><span class="force-glyph">${e.glyph}</span><p class="eyebrow">33 PIEZAS</p><h2>${e.name}</h2><p>${e.description}</p><strong>Entrar a la fuerza →</strong></div></a>`).join('')}</section></main>`}}


function elementView(key){const element=elementDefinitions.find(e=>e.key===key);if(!element)return notFoundView();const pieces=elementPieces.filter(p=>p.element===key);const levelSection=(level,items)=>`<section class="element-level level-${level.key}" data-level-section="${level.key}"><header><div><p class="eyebrow">${level.label}</p><h2>${level.meaning}</h2></div><span>${items.length} piezas</span></header><div class="element-piece-field">${items.map(p=>`<a class="element-piece-artifact ${level.key==='sod2'?'origin-piece':''}" href="/elementos/${key}/${p.number}" data-link data-piece-search="${(p.title+p.levelLabel+p.geometricMotif+p.number).toLowerCase()}" style="--element:${element.color};--artifact-image:url('${element.visual}')"><div class="element-piece-image"></div><div class="element-piece-glow"></div><span class="element-piece-number">${String(p.number).padStart(2,'0')}</span><div><p>${p.levelLabel}</p><strong>${p.title}</strong><small>${p.geometricMotif}</small></div></a>`).join('')}</div></section>`;return{title:element.name,html:`<main id="app-main" class="element-world" style="--element:${element.color};--element-image:url('${element.visual}')"><section class="element-world-hero"><div class="element-world-bg"></div><div class="element-world-shade"></div><div class="container element-world-copy"><p class="eyebrow">ELEMENTOS 33 · FUERZA 0${elementDefinitions.indexOf(element)+1}</p><span class="element-world-glyph">${element.glyph}</span><h1>${element.name}</h1><p>${element.description}</p>${element.placeholder?'<span class="placeholder-badge">ARTE DEFINITIVO PENDIENTE · PLACEHOLDER ACTIVO</span>':''}<div class="actions"><a class="btn" href="/elementos" data-link>Volver a las cinco fuerzas</a></div></div></section><section class="element-codex"><div class="container"><div class="element-toolbar"><div><p class="eyebrow">CÓDICE DE ${element.name.toUpperCase()}</p><h2>De lo visible al origen.</h2></div><div class="element-toolbar-controls"><select class="search-input" id="level-filter"><option value="">Todos los niveles</option>${levelDefinitions.map(l=>`<option value="${l.key}">${l.label}</option>`).join('')}</select><input class="search-input" id="piece-search" placeholder="Buscar pieza, nivel o motivo"><span class="pill" id="piece-count">33 piezas</span></div></div><div id="element-levels">${levelDefinitions.map(level=>levelSection(level,pieces.filter(p=>p.level===level.key))).join('')}</div></div></section></main>`,mount(){const filter=()=>{const level=document.querySelector('#level-filter').value;const q=document.querySelector('#piece-search').value.toLowerCase();let count=0;document.querySelectorAll('[data-level-section]').forEach(section=>{let visible=0;section.querySelectorAll('[data-piece-search]').forEach(card=>{const show=(!q||card.dataset.pieceSearch.includes(q))&&(!level||section.dataset.levelSection===level);card.hidden=!show;if(show){visible++;count++}});section.hidden=visible===0});document.querySelector('#piece-count').textContent=`${count} piezas`};document.querySelector('#level-filter').onchange=filter;document.querySelector('#piece-search').oninput=filter}}}


function pieceDetailView(elementKey,number){const piece=getPiece(elementKey,number);if(!piece)return notFoundView();const element=elementDefinitions.find(e=>e.key===elementKey);const saved=state().collection.pieces.includes(piece.id);return{title:piece.title,html:`<main id="app-main" class="piece-experience" style="--element:${element.color};--piece-image:url('${element.visual}')"><section class="piece-experience-hero"><div class="piece-experience-bg"></div><div class="piece-experience-shade"></div><div class="container piece-experience-copy"><p class="eyebrow">${piece.elementName.toUpperCase()} · ${piece.levelLabel.toUpperCase()}</p><span class="piece-hero-number">${String(piece.number).padStart(2,'0')}</span><span class="piece-hero-glyph">${piece.symbol}</span><h1>${piece.title}</h1><p>${piece.phrase}</p>${element.placeholder?'<span class="placeholder-badge">PLACEHOLDER VISUAL</span>':''}<div class="actions"><button class="btn btn-primary" data-piece-practice>Vivir la experiencia</button><button class="btn" data-save-piece>${saved?'Quitar de mi archivo':'Guardar en mi archivo'}</button><a class="btn btn-ghost" href="/elementos/${elementKey}" data-link>Volver a ${piece.elementName}</a></div></div></section><section class="piece-reading"><div class="container"><article><p class="eyebrow">INTERPRETACIÓN</p><h2>Una lectura, no una doctrina.</h2><p>${piece.interpretation}</p></article><article><p class="eyebrow">APLICACIÓN</p><h2>La comprensión necesita evidencia.</h2><p>${piece.practicalApplication}</p></article><aside><p class="eyebrow">RELACIONES</p><div class="tag-list">${piece.keywords.map(k=>`<span class="tag">${k}</span>`).join('')}</div><p class="muted">Motivo: ${piece.geometricMotif}<br>Edición: ${piece.edition}<br>Profundidad: ${piece.rarity}</p></aside></div></section></main>`,mount(){document.querySelector('[data-save-piece]').onclick=e=>{store.update(s=>{const list=s.collection.pieces;const i=list.indexOf(piece.id);i>=0?list.splice(i,1):list.push(piece.id);return s});e.currentTarget.textContent=state().collection.pieces.includes(piece.id)?'Quitar de mi archivo':'Guardar en mi archivo';toast('Archivo personal actualizado')};document.querySelector('[data-piece-practice]').onclick=()=>openModal({title:`Experiencia · ${piece.title}`,content:`<p class="lead" style="font-size:20px">${piece.practicalApplication}</p><p class="muted">Contenido placeholder funcional. Un Código solo puede conservarse si reconocés una transición.</p><form class="form" id="piece-practice"><div class="field"><label>Antes</label><textarea name="before" required></textarea></div><div class="field"><label>Después</label><textarea name="after" required></textarea></div><label class="option"><input type="checkbox" name="transition" required><strong>Reconozco que algo cambió en cómo observo o actúo.</strong></label><button class="btn btn-primary">Conservar como Código</button></form>`,onMount:(root,close)=>{root.querySelector('form').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const now=new Date();store.update(s=>{s.codes=[...(s.codes||[]),{id:`SOD-${Date.now()}`,title:`Integración de ${piece.title}`,type:'Integración',depth:(s.codes||[]).length?'Común':'Fundacional',createdAt:now.toISOString(),date:now.toLocaleDateString('es-AR'),originUniverse:'elements33',originEvent:'element_practice_transition',summary:String(fd.get('after')),meaning:`Antes: ${String(fd.get('before'))}`,visual:'/assets/sod-visual/044.png',linkedSeedIds:[],linkedElementIds:[piece.id],userConfirmed:true,privacy:'private',status:'active'}];return s});toast('Código SØD conservado');close()}}})}}}


function codeCard(code){return `<article class="code-card" style="--code-image:url('${code.visual||'/assets/sod-visual/042.png'}')"><div class="code-card-shade"></div><div class="code-card-content"><span class="eyebrow">${escapeHtml(code.type)} · ${escapeHtml(code.depth||'Común')}</span><h3>${escapeHtml(code.title)}</h3><p>${escapeHtml(code.summary)}</p><small>${escapeHtml(code.date||'')}</small></div></article>`}

function codesView(){const codes=state().codes||[];const active=codes[0]||sampleCodes[0];const archive=codes.length?codes:sampleCodes;return{title:'Códigos SØD',html:`<main id="app-main" class="codes-museum" style="--museum-bg:url('/assets/sod-visual/046.png')"><div class="codes-museum-shade"></div><section class="codes-museum-intro container"><p class="eyebrow">BIBLIOTECA PERSONAL</p><h1>Códigos SØD.<br><span>Evidencia del recorrido.</span></h1><p>Las Semillas transforman. Los Códigos conservan el momento en que algo realmente cambió.</p>${codes.length?'':'<span class="placeholder-badge">MODO DEMOSTRACIÓN · LAS RELIQUIAS VISIBLES SON PLACEHOLDERS</span>'}</section><section class="code-exhibition container"><div class="code-pedestal"><div class="code-pedestal-image" style="--code-image:url('${active.visual||'/assets/sod-visual/042.png'}')"></div><div class="code-pedestal-ring"></div></div><article class="code-story"><p class="eyebrow">${escapeHtml(active.type)} · ${escapeHtml(active.depth||'Común')}</p><h2>${escapeHtml(active.title)}</h2><p>${escapeHtml(active.summary)}</p><dl><div><dt>Origen</dt><dd>${escapeHtml(active.originUniverse||'Demostración')}</dd></div><div><dt>Fecha</dt><dd>${escapeHtml(active.date||'Placeholder')}</dd></div><div><dt>Privacidad</dt><dd>${escapeHtml(active.privacy||'Privado')}</dd></div></dl><div class="actions"><a class="btn btn-primary" href="/experiencia" data-link>Iniciar una transformación</a><a class="btn" href="/coleccion" data-link>Abrir museo personal</a></div></article></section><section class="code-archive-strip"><div class="container"><p class="eyebrow">RELIQUIAS DEL ARCHIVO</p><div class="code-relic-rail">${archive.map((c,i)=>`<article class="code-relic-mini ${i===0?'active':''}" style="--code-image:url('${c.visual||'/assets/sod-visual/042.png'}')"><div></div><span>${String(i+1).padStart(2,'0')}</span><strong>${escapeHtml(c.title)}</strong></article>`).join('')}</div></div></section></main>`}}


function observatoryView(){const s=state();const seedCount=s.collection.seeds.length;const codeCount=(s.codes||[]).length;const habits=s.journey.completedDays.length;const active=seedCount+codeCount+habits;return{title:'Observatorio',html:`<main id="app-main" class="observatory-page observatory-v3" style="--observatory-image:url('/assets/sod-visual/038.png')"><div class="observatory-shade"></div><div class="observatory-world-signals" aria-hidden="true"><span class="world-tree ${seedCount?'visible':''}" style="--x:24%;--y:68%">✦</span><span class="world-tree ${seedCount>2?'visible':''}" style="--x:72%;--y:61%">✦</span><span class="world-monument ${codeCount?'visible':''}" style="--x:51%;--y:54%">◇</span><span class="world-path ${habits?'visible':''}"></span><span class="world-constellation ${codeCount?'visible':''}"></span></div><div class="container observatory-content"><p class="eyebrow">META-UNIVERSO</p><h1 class="page-title">¿En quién me estoy convirtiendo?</h1><p class="lead">No muestra progreso. Muestra relaciones. El paisaje interpreta lo que normalmente permanecería invisible.</p><div class="observatory-story-grid"><article class="observatory-narrative"><p>${active?'Tu mundo ya conserva huellas reales. Cada brote, reliquia y tramo de sendero está vinculado con una experiencia registrada.':'El paisaje todavía está casi vacío. No porque no haya potencial, sino porque la historia recién comienza.'}</p><div class="actions"><a class="btn btn-primary" href="/experiencia" data-link>${active?'Continuar el recorrido':'Iniciar la primera transformación'}</a><a class="btn" href="/codigos" data-link>Recorrer Códigos</a><a class="btn btn-ghost" href="/hub" data-link>Volver al Hub</a></div></article><div class="observatory-relations"><p class="eyebrow">RELACIONES VISIBLES</p><div><span>${seedCount}</span><p><strong>Brotes</strong><small>Semillas descubiertas o cultivadas.</small></p></div><div><span>${codeCount}</span><p><strong>Monumentos</strong><small>Transiciones que decidiste conservar.</small></p></div><div><span>${habits}</span><p><strong>Senderos</strong><small>Acciones sostenidas en el tiempo.</small></p></div></div></div></div></main>`}}


function collectionView(){const s=state();const collectedSeeds=seeds.filter(x=>s.collection.seeds.includes(x.id));const pieces=s.collection.pieces.map(id=>elementPieces.find(x=>x.id===id)).filter(Boolean);const codes=s.codes||[];return{title:'Biblioteca Personal',html:`<main id="app-main">${pageHero('BIBLIOTECA PERSONAL','Un museo de la evolución.<br><span style="color:var(--cyan)">No una carpeta.</span>','Semillas descubiertas, Códigos del recorrido y principios de Elementos 33 conviven sin confundirse.')}<section class="section" style="padding-top:10px"><div class="container"><h2>Códigos SØD</h2><div class="code-grid">${codes.map(codeCard).join('')}</div><div class="divider"></div><h2>Semillas cultivadas</h2>${collectedSeeds.length?`<div class="seed-grid">${collectedSeeds.map(seedCard).join('')}</div>`:'<div class="empty">Todavía no cultivaste Semillas.</div>'}<div class="divider"></div><h2>Elementos 33</h2>${pieces.length?`<div class="piece-grid">${pieces.map(p=>{const e=elementDefinitions.find(x=>x.key===p.element);return `<a class="piece" href="/elementos/${p.element}/${p.number}" data-link style="--piece-color:${e.color}44"><span class="piece-number">${String(p.number).padStart(2,'0')}</span><span class="piece-level">${p.elementName}</span></a>`}).join('')}</div>`:'<div class="empty">Todavía no guardaste piezas.</div>'}</div></section></main>`}}

function marketplaceView(){return{title:'La Forja',html:`<main id="app-main" class="visual-page" style="--visual-bg:url('/assets/sod-visual/046.png')"><div class="visual-page-shade"></div><div class="visual-page-content">${pageHero('LA FORJA · PRÓXIMAMENTE','Recursos para continuar.<br><span style="color:var(--gold)">Nunca el centro del viaje.</span>','La Forja permanecerá en la periferia del ecosistema y solo ofrecerá herramientas, experiencias y creadores alineados con la constitución de SØD.')}<section class="section" style="padding-top:10px"><div class="container"><article class="card"><div class="card-body"><span class="pill">CAPA FUTURA</span><h2 style="font-size:42px;margin-top:24px">Todavía no abrimos esta puerta.</h2><p class="lead">No inventamos contratos, precios, supply ni propiedad. El crecimiento personal no será interrumpido por promociones dentro del Hub.</p><a class="btn" href="/hub" data-link>Volver al Hub</a></div></article></div></section></div></main>`}}

function profileView(){const s=state();const completion=s.journey.completedDays.length;return{title:'Identidad',html:`<main id="app-main" class="visual-page" style="--visual-bg:url('/assets/sod-visual/055.png')"><div class="visual-page-shade"></div><div class="visual-page-content">${pageHero('IDENTIDAD','¿Quién sos hoy?','Identidad no es Ajustes. Es una representación revisable de tu historia, valores, dirección y forma de ser acompañado.')}<section class="section" style="padding-top:10px"><div class="container"><div class="grid grid-4"><article class="card metric"><span class="eyebrow">RECORRIDO</span><strong>${completion}</strong><span class="muted">integraciones</span></article><article class="card metric"><span class="eyebrow">SEMILLAS</span><strong>${s.collection.seeds.length}</strong><span class="muted">descubiertas</span></article><article class="card metric"><span class="eyebrow">CÓDIGOS</span><strong>${(s.codes||[]).length}</strong><span class="muted">momentos conservados</span></article><article class="card metric"><span class="eyebrow">CONVERSACIONES</span><strong>${Math.floor((s.dialogue||[]).length/2)}</strong><span class="muted">capítulos</span></article></div><div class="grid grid-2" style="margin-top:18px"><article class="card"><div class="card-body"><h2>${escapeHtml(s.profile.name)}</h2><p class="muted">Esta identidad debe evolucionar con vos y nunca convertirse en una etiqueta fija o un diagnóstico.</p><div class="actions"><a class="btn btn-primary" href="/observatorio" data-link>Contemplar evolución</a><a class="btn" href="/coleccion" data-link>Biblioteca Personal</a></div></div></article><article class="card"><div class="card-body"><h2>Control</h2><p class="muted">La memoria debe poder revisarse, corregirse, exportarse y olvidarse.</p><div class="actions"><a class="btn" href="/configuracion" data-link>Ajustes técnicos</a><a class="btn" href="/privacidad" data-link>Privacidad y memoria</a></div></div></article></div></div></section></div></main>`}}

function configView(){const s=state();return{title:'Configuración',html:`<main id="app-main" class="calibration-world" style="--calibration-bg:url('/assets/sod-visual/061.png')"><div class="calibration-shade"></div><section class="calibration-layout container"><div class="calibration-preview"><p class="eyebrow">CÁMARA DE CALIBRACIÓN</p><h1>La inmersión también debe darte control.</h1><p>Los cambios se reflejan en esta maqueta y permanecen en el dispositivo.</p><div class="calibration-core ${s.settings.motion?'alive':''}"><span>Ø</span><i></i><i></i><i></i></div><div class="calibration-preview-meta"><span>${s.settings.quality.toUpperCase()}</span><span>${s.settings.audio?'AUDIO ACTIVO':'SILENCIO'}</span><span>${s.settings.motion?'MUNDO VIVO':'MOVIMIENTO REDUCIDO'}</span></div></div><div class="calibration-console"><p class="eyebrow">PREFERENCIAS</p><div class="settings-list"><div class="setting-row"><div><strong>Audio ambiental</strong><div class="muted">Generativo, sin voz y siempre opt-in.</div></div><button class="switch ${s.settings.audio?'on':''}" data-toggle="audio" role="switch" aria-checked="${s.settings.audio}"><span></span></button></div><div class="setting-row"><div><strong>Movimiento dinámico</strong><div class="muted">Respiración, partículas y transiciones.</div></div><button class="switch ${s.settings.motion?'on':''}" data-toggle="motion" role="switch" aria-checked="${s.settings.motion}"><span></span></button></div><div class="setting-row"><div><strong>Alto contraste</strong><div class="muted">Refuerza texto, bordes y foco.</div></div><button class="switch ${s.settings.highContrast?'on':''}" data-toggle="highContrast" role="switch" aria-checked="${s.settings.highContrast}"><span></span></button></div><div class="setting-row"><div><strong>Reducir efectos</strong><div class="muted">Desactiva blur y recursos decorativos.</div></div><button class="switch ${s.settings.reduceEffects?'on':''}" data-toggle="reduceEffects" role="switch" aria-checked="${s.settings.reduceEffects}"><span></span></button></div><div class="setting-row"><div><label for="quality"><strong>Calidad gráfica</strong></label><div class="muted">Conservadora por defecto.</div></div><select id="quality" class="search-input"><option value="auto" ${s.settings.quality==='auto'?'selected':''}>Automática</option><option value="low" ${s.settings.quality==='low'?'selected':''}>Esencial</option><option value="high" ${s.settings.quality==='high'?'selected':''}>Alta</option></select></div><div class="setting-row"><div><label for="volume"><strong>Volumen ambiente</strong></label><div class="muted">Independiente y persistente.</div></div><input id="volume" type="range" min="0" max="1" step="0.05" value="${s.settings.ambientVolume}"></div><div class="setting-row danger-setting"><div><strong>Datos locales</strong><div class="muted">Restablece onboarding, progreso, colección y preferencias.</div></div><button class="btn btn-danger" data-reset>Restablecer</button></div></div></div></section></main>`,mount(){const refreshSwitch=(btn,val)=>{btn.classList.toggle('on',val);btn.setAttribute('aria-checked',String(val));document.querySelector('.calibration-core')?.classList.toggle('alive',state().settings.motion)};document.querySelectorAll('[data-toggle]').forEach(btn=>btn.onclick=async()=>{const key=btn.dataset.toggle;const val=!state().settings[key];store.update(s=>{s.settings[key]=val;return s});refreshSwitch(btn,val);if(key==='audio'){if(val)await ambient.start(state().settings.ambientVolume);else ambient.stop()}if(key==='highContrast')document.body.classList.toggle('high-contrast',val);if(key==='reduceEffects')document.body.classList.toggle('reduce-effects',val);toast('Preferencia actualizada')});document.querySelector('#quality').onchange=e=>{store.update(s=>{s.settings.quality=e.target.value;return s});toast('Calidad actualizada')};document.querySelector('#volume').oninput=e=>{const val=Number(e.target.value);store.update(s=>{s.settings.ambientVolume=val;return s});ambient.setVolume(val)};document.querySelector('[data-reset]').onclick=()=>confirmAction('Esto borrará el progreso y las preferencias locales. La bitácora persistida en el servidor no se elimina.',()=>{store.reset();toast('Datos locales restablecidos');navigate('/')})}}}


function privacyView(){return{title:'Privacidad',html:`<main id="app-main">${pageHero('PRIVACIDAD','La introspección no debe convertirse<br><span style="color:var(--cyan)">en materia prima de vigilancia.</span>','Política funcional del MVP y límites que la arquitectura debe conservar.')}<section class="section" style="padding-top:10px"><div class="container grid grid-2"><article class="card"><div class="card-body"><h2>Qué se guarda</h2><p class="muted">Preferencias, progreso, colección y diálogo reciente se guardan localmente en el navegador. La bitácora usa el archivo de datos del servidor local del MVP.</p></div></article><article class="card"><div class="card-body"><h2>Qué no se envía</h2><p class="muted">El texto privado de diálogos y bitácora no se envía a analytics. Esta versión no incorpora trackers de terceros.</p></div></article><article class="card"><div class="card-body"><h2>Límites de SØD</h2><p class="muted">El diálogo es reflexión guiada, no terapia, diagnóstico, asesoramiento médico, legal ni autoridad absoluta.</p></div></article><article class="card"><div class="card-body"><h2>Control</h2><p class="muted">Podés borrar el estado local desde Configuración y eliminar registros individuales de la Bitácora.</p><a class="btn btn-small" href="/configuracion" data-link>Abrir configuración</a></div></article></div></section></main>`}}

function adminView(){return{title:'Admin',html:`<main id="app-main">${pageHero('ADMIN · LOCAL FIRST','Contenido operativo<br><span style="color:var(--cyan)">sin tocar componentes.</span>','Panel básico para editar mensaje, clave y anuncio. En producción debe protegerse por roles y sesiones reales.')}<section class="section" style="padding-top:10px"><div class="container grid grid-2"><article class="card"><div class="card-body"><h2>Contenido del Hub</h2><form class="form" id="admin-form"><div class="field"><label for="dailyMessage">Mensaje diario</label><textarea id="dailyMessage" name="dailyMessage"></textarea></div><div class="field"><label for="dailyKey">Clave del día</label><input id="dailyKey" name="dailyKey" maxlength="180"></div><div class="field"><label for="announcement">Anuncio</label><textarea id="announcement" name="announcement"></textarea></div><button class="btn btn-primary">Guardar cambios en este dispositivo</button></form></div></article><article class="card"><div class="card-body"><h2>Estado del contenido</h2><table class="admin-table"><tbody><tr><th>Universos</th><td>${universes.length} activos</td></tr><tr><th>Semillas base</th><td>${seeds.length}</td></tr><tr><th>Elementos 33</th><td>${elementPieces.length}</td></tr><tr><th>Journeys</th><td>1 · 14 días</td></tr><tr><th>Blockchain</th><td>Feature flag apagado</td></tr><tr><th>LLM</th><td>Adaptador scripted</td></tr></tbody></table><div class="divider"></div><p class="muted">Importación JSON/CSV, versionado editorial, media manager y RBAC quedan documentados como siguiente iteración real.</p></div></article></div></section></main>`,mount(){const form=document.querySelector('#admin-form');api.getAdmin().then(r=>{form.dailyMessage.value=r.content.dailyMessage||'';form.dailyKey.value=r.content.dailyKey||'';form.announcement.value=r.content.announcement||''}).catch(err=>toast(err.message,'error'));form.onsubmit=async e=>{e.preventDefault();const fd=new FormData(form);try{await api.saveAdmin(Object.fromEntries(fd));toast('Contenido publicado')}catch(err){toast(err.message,'error')}}}}}

function transformationView(){return{title:'Primera transformación',html:`<main id="app-main" class="transformation-world" style="--transformation-image:url('/assets/sod-visual/016.png')"><div class="transformation-bg"></div><div class="transformation-shade"></div><section class="transformation-shell"><div class="transformation-progress"><span data-progress></span></div><aside class="transformation-presence"><p class="eyebrow">SØD · EXPERIENCIA DE CLARIDAD</p><div class="transformation-core"><img data-core-image src="/assets/sod-visual/016.png" alt="Estado visual del núcleo SØD"></div><blockquote data-core-phrase>Traé aquello que todavía no lográs ordenar.</blockquote><small>Contenido y razonamiento en modo MVP. La estructura representa la experiencia final.</small></aside><div class="transformation-stage" id="transformation-stage"></div></section></main>`,mount(){let step=0;const data={issue:'',reply:'',facts:'',interpretation:'',emotion:'',uncertainty:'',q1:'',q2:'',q3:'',before:'',after:'',seed:null,evidence:'',codeTitle:''};const stage=document.querySelector('#transformation-stage');const root=document.querySelector('.transformation-world');const progress=document.querySelector('[data-progress]');const core=document.querySelector('[data-core-image]');const phrase=document.querySelector('[data-core-phrase]');const states=[['016','escucha'],['019','procesamiento'],['017','cartografía'],['018','testigo'],['021','descubrimiento'],['042','evidencia'],['038','integración']];const updateAtmosphere=()=>{const [img,label]=states[Math.min(step,states.length-1)];root.style.setProperty('--transformation-image',`url('/assets/sod-visual/${img}.png')`);core.src=`/assets/sod-visual/${img}.png`;core.alt=`Núcleo SØD en estado de ${label}`;progress.style.width=`${((step+1)/7)*100}%`};const field=(name,label,placeholder,value='')=>`<div class="field"><label for="${name}">${label}</label><textarea id="${name}" name="${name}" required placeholder="${placeholder}">${escapeHtml(value)}</textarea></div>`;const render=()=>{updateAtmosphere();if(step===0){phrase.textContent='No necesitás formularlo perfectamente.';stage.innerHTML=`<p class="eyebrow">01 · ENTRADA</p><h1>¿Qué está ocupando tu mente en este momento?</h1><p class="lead">SØD no empieza respondiendo. Empieza comprendiendo qué pregunta necesita realmente ser observada.</p><form class="form" data-form="issue">${field('issue','Lo que está presente','Escribí como te salga.','')}<button class="btn btn-primary">Permitir que SØD observe</button><a class="btn btn-ghost" href="/hub" data-link>Volver al Hub</a></form>`}
else if(step===1){phrase.textContent='Primero separamos el ruido.';stage.innerHTML=`<p class="eyebrow">02 · ESPEJO</p><h1>SØD devuelve lo que observa.</h1><div class="sod-response"><span>Ø</span><p>${escapeHtml(data.reply)}</p></div><p class="lead">Todavía no es una verdad. Es una lectura posible que vamos a ordenar.</p><button class="btn btn-primary" data-next>Construir mapa de claridad</button>`}
else if(step===2){phrase.textContent='Hecho, interpretación, emoción e incertidumbre.';stage.innerHTML=`<p class="eyebrow">03 · CARTÓGRAFO</p><h1>Separá lo que hoy aparece mezclado.</h1><form class="form cognitive-map-form" data-form="map">${field('facts','Hechos','¿Qué ocurrió concretamente, sin explicación?',data.facts)}${field('interpretation','Interpretación','¿Qué significado le estás dando?',data.interpretation)}${field('emotion','Emoción','¿Qué sentís y dónde aparece?',data.emotion)}${field('uncertainty','Incertidumbre','¿Qué todavía no sabés?',data.uncertainty)}<button class="btn btn-primary">Continuar</button></form>`}
else if(step===3){phrase.textContent='Una pregunta adecuada puede cambiar el mapa.';stage.innerHTML=`<p class="eyebrow">04 · PROFUNDIZACIÓN</p><h1>Tres preguntas inesperadas.</h1><form class="form" data-form="questions">${field('q1','1. ¿Qué parte de esto depende realmente de vos?','No respondas lo que debería depender. Respondé lo que depende.',data.q1)}${field('q2','2. ¿Qué decisión estás evitando al pedir más claridad?','Puede ser pequeña, reversible o simplemente admitir que todavía no sabés.',data.q2)}${field('q3','3. ¿Qué cambiaría si dejaras de defender tu primera interpretación?','Explorá otra lectura posible.',data.q3)}<button class="btn btn-primary">Ver el mapa completo</button></form>`}
else if(step===4){phrase.textContent='La claridad no elimina la incertidumbre. Reduce el ruido.';stage.innerHTML=`<p class="eyebrow">05 · TRANSICIÓN</p><h1>¿Cambió algo en cómo observás la situación?</h1><div class="clarity-map-summary"><article><span>HECHO</span><p>${escapeHtml(data.facts)}</p></article><article><span>INTERPRETACIÓN</span><p>${escapeHtml(data.interpretation)}</p></article><article><span>EMOCIÓN</span><p>${escapeHtml(data.emotion)}</p></article><article><span>INCERTIDUMBRE</span><p>${escapeHtml(data.uncertainty)}</p></article></div><form class="form" data-form="transition">${field('before','Antes','¿Cómo observabas esto al comenzar?',data.before||data.issue)}${field('after','Ahora','¿Qué podés distinguir ahora que antes estaba mezclado?',data.after)}<div class="actions"><button class="btn btn-primary" name="transition" value="yes">Sí, existe una transición</button><button class="btn" type="button" data-no-transition>Todavía no</button></div></form>`}
else if(step===5){phrase.textContent='La Semilla ya existía. Tu recorrido permitió descubrirla.';stage.innerHTML=`<p class="eyebrow">06 · SEMILLA DESCUBIERTA</p><h1>Una comprensión estaba esperando.</h1><article class="discovered-seed" style="--seed-image:url('${data.seed.image}')"><div></div><section><p class="eyebrow">SEMILLA CANÓNICA · ${data.seed.element.toUpperCase()}</p><h2>${escapeHtml(data.seed.title)}</h2><p>${escapeHtml(data.seed.interpretation)}</p><blockquote>${escapeHtml(data.seed.application)}</blockquote></section></article><p class="muted">Descubrir no es integrar. La Semilla germina cuando deja evidencia en una conducta, decisión o forma de interpretar.</p><button class="btn btn-primary" data-next>Aceptar la práctica</button>`}
else if(step===6){phrase.textContent='El Código conserva el momento. No reemplaza la comprensión.';stage.innerHTML=`<p class="eyebrow">07 · EVIDENCIA</p><h1>¿Querés conservar este momento?</h1><p class="lead">Un Código SØD solo existe porque ocurrió una transición real y vos elegís preservarla.</p><form class="form" data-form="code"><div class="field"><label for="codeTitle">Título de la reliquia</label><input id="codeTitle" name="codeTitle" value="${escapeHtml(data.codeTitle||'El momento en que algo dejó de estar mezclado')}" required></div>${field('evidence','Evidencia de integración','¿Qué acción, observación o decisión va a demostrar que esta comprensión produjo un cambio?',data.evidence)}<label class="option"><input type="checkbox" name="consent" required><strong>Quiero conservar este momento como Código privado.</strong><small>Podrás revisarlo, editarlo o eliminarlo.</small></label><div class="actions"><button class="btn btn-primary">Crear Código SØD</button><button class="btn" type="button" data-skip-code>No conservarlo ahora</button></div></form>`}
else{phrase.textContent='Tu universo cambió porque algo en vos también cambió.';stage.innerHTML=`<p class="eyebrow">TRANSFORMACIÓN REGISTRADA</p><h1>El mundo conserva una nueva huella.</h1><p class="lead">Descubriste una Semilla, elegiste una práctica y conservaste la transición como Código SØD. El Observatorio ya puede reflejarla.</p><div class="completion-artifacts"><article><span>✦</span><p>Semilla descubierta</p><strong>${escapeHtml(data.seed.title)}</strong></article><article><span>◇</span><p>Código conservado</p><strong>${escapeHtml(data.codeTitle)}</strong></article><article><span>→</span><p>Práctica</p><strong>${escapeHtml(data.evidence)}</strong></article></div><div class="actions"><a class="btn btn-primary" href="/observatorio" data-link>Contemplar el cambio</a><a class="btn" href="/codigos" data-link>Ver mi Código</a><a class="btn btn-ghost" href="/hub" data-link>Volver al Hub</a></div>`}bindRouteButtons(stage);bind()};const bind=()=>{stage.querySelector('[data-next]')?.addEventListener('click',()=>{step++;render()});stage.querySelector('[data-no-transition]')?.addEventListener('click',()=>{toast('No se crea un Código si no hubo transición');step=2;render()});stage.querySelector('[data-skip-code]')?.addEventListener('click',()=>{toast('El momento no fue conservado. La decisión permanece bajo tu control.');navigate('/hub')});const form=stage.querySelector('form');if(!form)return;form.onsubmit=async e=>{e.preventDefault();const fd=new FormData(form);const kind=form.dataset.form;if(kind==='issue'){data.issue=String(fd.get('issue')).trim();if(!data.issue)return;form.querySelector('button').disabled=true;try{const result=await api.dialogue(data.issue);data.reply=result.reply;store.update(s=>{s.dialogue=[...(s.dialogue||[]),{role:'user',text:data.issue},{role:'sod',text:data.reply}].slice(-30);return s});step=1;render()}catch(err){toast(err.message,'error');form.querySelector('button').disabled=false}}
else if(kind==='map'){['facts','interpretation','emotion','uncertainty'].forEach(k=>data[k]=String(fd.get(k)));step=3;render()}
else if(kind==='questions'){['q1','q2','q3'].forEach(k=>data[k]=String(fd.get(k)));step=4;render()}
else if(kind==='transition'){data.before=String(fd.get('before'));data.after=String(fd.get('after'));data.seed=selectSeedFor(`${data.issue} ${data.after} ${data.q1} ${data.q2} ${data.q3}`);store.update(s=>{if(!s.collection.seeds.includes(data.seed.id))s.collection.seeds.push(data.seed.id);s.collection.seedStates=s.collection.seedStates||{};s.collection.seedStates[data.seed.id]='discovered';return s});step=5;render()}
else if(kind==='code'){data.codeTitle=String(fd.get('codeTitle'));data.evidence=String(fd.get('evidence'));const now=new Date();store.update(s=>{const first=(s.codes||[]).length===0;s.codes=[...(s.codes||[]),{id:`SOD-${Date.now()}`,title:data.codeTitle,type:'Conversación',depth:first?'Fundacional':'Común',createdAt:now.toISOString(),date:now.toLocaleDateString('es-AR'),originUniverse:'sod',originEvent:'clarity_transition_confirmed',summary:data.after,meaning:`Antes: ${data.before}`,visual:'/assets/sod-visual/042.png',linkedSeedIds:[data.seed.id],memories:[],nextRecommendation:data.evidence,linkedCodeIds:[],privacy:'private',userConfirmed:true,status:'active'}];s.transformation={lastCompletedAt:now.toISOString(),before:data.before,after:data.after,seedId:data.seed.id};return s});step=7;render()}}};render()}}}

function notFoundView(){return{title:'Puerta no encontrada',html:`<main id="app-main" class="section"><div class="container"><div class="empty"><div style="font-size:80px;color:var(--cyan)">Ø</div><h1>Esta puerta todavía no existe.</h1><p>La ruta solicitada no corresponde a un universo activo.</p><a class="btn btn-primary" href="/hub" data-link>Volver al Hub</a></div></div></main>`}}

export function getView(route){
  if(route==='/')return portalView();
  if(route==='/entrar')return authView('login');
  if(route==='/registro')return authView('register');
  if(route==='/onboarding')return onboardingView();
  if(route==='/hub')return hubView();
  if(route==='/hub-2d')return fallbackHubView();
  if(route==='/experiencia')return transformationView();
  const universe=route.match(/^\/universos\/([^/]+)$/);if(universe)return universeView(decodeURIComponent(universe[1]));
  if(route==='/journey'||route.startsWith('/journey/'))return journeyView();
  if(route==='/bitacora')return bitacoraView();
  if(route==='/biblioteca')return libraryView();
  if(route==='/semillas')return seedsView();
  const seed=route.match(/^\/semillas\/([^/]+)$/);if(seed)return seedDetailView(decodeURIComponent(seed[1]));
  if(route==='/elementos')return elementsView();
  const piece=route.match(/^\/elementos\/([^/]+)\/(\d+)$/);if(piece)return pieceDetailView(piece[1],piece[2]);
  const element=route.match(/^\/elementos\/([^/]+)$/);if(element)return elementView(element[1]);
  if(route==='/codigos')return codesView();
  if(route==='/observatorio')return observatoryView();
  if(route==='/coleccion')return collectionView();
  if(route==='/marketplace')return marketplaceView();
  if(route==='/perfil')return profileView();
  if(route==='/configuracion')return configView();
  if(route==='/privacidad')return privacyView();
  if(route==='/admin')return adminView();
  return notFoundView();
}
